import fs from 'node:fs';
import crypto from 'node:crypto';
import ts from 'typescript';
const manifest=JSON.parse(fs.readFileSync('.planning/memory-resilience/quality-classifications.json','utf8'));
const rows=[];
const label=node=>{
 if(ts.isCallExpression(node))return label(node.expression)+'(...)';
 if(ts.isPropertyAccessExpression(node))return label(node.expression)+'.'+node.name.text;
 if(ts.isElementAccessExpression(node))return label(node.expression)+'['+node.argumentExpression.getText()+']';
 return node.getText().replaceAll(/\s+/g,' ');
};
for(const file of manifest.files.filter(f=>f.tier===null)) {
 const source=fs.readFileSync(file.path,'utf8');
 const runtime=ts.transpileModule(source,{fileName:file.path,compilerOptions:{target:ts.ScriptTarget.ESNext,module:ts.ModuleKind.ESNext,verbatimModuleSyntax:true,removeComments:true}}).outputText;
 const ast=ts.createSourceFile(file.path+'.js',runtime,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS);
 const imports=ast.statements.filter(ts.isImportDeclaration).map(n=>n.getText(ast));
 const calls=new Set(),constructors=new Set(),dynamic=[],effects=[];
 const visit=node=>{
  if(ts.isCallExpression(node)) {
   const name=label(node.expression);
   calls.add(name);
   if(node.expression.kind===ts.SyntaxKind.ImportKeyword || name==='require' || name==='eval' || name==='Function')dynamic.push(node.getText(ast));
  }
  if(ts.isNewExpression(node))constructors.add(node.getText(ast).replaceAll(/\s+/g,' '));
  if(ts.isBinaryExpression(node) && ts.isAssignmentOperator(node.operatorToken.kind) && /^(process|global|globalThis|console|Date|Math)\b/.test(node.left.getText(ast)))effects.push(node.getText(ast));
  if(ts.isDeleteExpression(node) && /^(process|global|globalThis|console|Date|Math)\b/.test(node.expression.getText(ast)))effects.push(node.getText(ast));
  ts.forEachChild(node,visit);
 };
 visit(ast);
 rows.push({path:file.path,sourceHash:crypto.createHash('sha256').update(source.replaceAll('\r\n','\n')).digest('hex'),runtimeHash:crypto.createHash('sha256').update(runtime).digest('hex'),imports,calls:[...calls].sort(),constructors:[...constructors],dynamic,effects});
}
fs.writeFileSync('.git/b04-runtime-call-index.json',JSON.stringify(rows,null,2)+'\n');
for(const row of rows.filter(r=>r.path.startsWith(process.argv[2]??'src/domain/'))) console.log(JSON.stringify({...row,constructors:row.constructors.map(c=>c.length>200?c.slice(0,200)+' [arguments summarized in display]':c),calls:row.calls.filter(c=>!c.startsWith('expect('))}));

