import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { sourceHash, validateInventory } from '../scripts/quality-inventory.ts';
const root = '.planning/memory-resilience/';
const read = (p: string) => JSON.parse(readFileSync(p,'utf8'));
const assert = (condition: unknown, message: string) => { if(!condition) throw new Error(message); };
const catalog = read(root+'executable-catalog.json');
const manifest = read(root+'quality-classifications.json');
const ledger = read(root+'work-items.json');
const mapping = read(root+'package-boundary-map.json');
for(const input of [...catalog.files,...catalog.packages,...mapping.sourceInputs]) assert(sourceHash(readFileSync(input.path,'utf8'))===input.sourceHash,'Stale source '+input.path);
const prior=JSON.parse(execFileSync('git',['show','HEAD:.planning/memory-resilience/quality-classifications.json'],{encoding:'utf8'}));
for(const old of prior.files.filter((f:any)=>f.tier!==null))assert(JSON.stringify(old)===JSON.stringify(manifest.files.find((f:any)=>f.path===old.path)),'Existing tier changed '+old.path);
const issues = validateInventory(catalog,manifest);
assert(issues.length===0,'Unexpected inventory errors');
assert(manifest.files.filter((f:any)=>f.tier!==null).length===446,'Wrong proposed count');
const catalogByPath=new Map(catalog.files.map((f:any)=>[f.path,f]));
assert(manifest.files.filter((f:any)=>f.tier===null).every((f:any)=>(catalogByPath.get(f.path) as any)?.syntax==='test-driver'),'Non-test candidate remains unclassified');
const byId = new Map<string,any>(ledger.items.map((i:any)=>[i.id,i]));
assert(byId.size===215 && byId.size===ledger.items.length,'Duplicate or missing work items');
const visited = new Set<string>();
function visit(id:string, parents = new Set<string>()) {
 assert(!parents.has(id),'Dependency cycle '+id);
 if(visited.has(id))return;
 assert(byId.has(id),'Unknown dependency '+id);
 const stack=new Set([...parents,id]);
 for(const dep of byId.get(id).depends_on) visit(dep,stack);
 visited.add(id);
}
for(const id of byId.keys())visit(id);
function reaches(id:string,target:string):boolean { return id===target || byId.get(id).depends_on.some((dep:string)=>reaches(dep,target)); }
for(const id of ['B11.1','B11.2','B11.3','B11.4',...Array.from({length:67},(_,i)=>'B11.'+(i+5)),'Q095','Q081','B12','D05','Q091','Q092','Q093','Q094','Q041'])assert(reaches('R02',id),'Finding bypasses baseline acceptance '+id);
for(const item of ledger.items.filter((i:any)=>i.id.startsWith('B11.') && i.id!=='B11.3'))assert(reaches('B09',item.id),'Full-suite rebaseline bypasses cleanup '+item.id);
assert(ledger.items.filter((i:any)=>i.status==='active').map((i:any)=>i.id).join()==='B04','Unexpected active item');
assert(byId.get('B05').status==='pending','B05 prematurely advanced');
const changed=execFileSync('git',['diff','--name-only'],{encoding:'utf8'}).trim().split('\n');
assert(changed.every(p=>p.startsWith('.planning/')),'Unexpected executable change');
const record={status:'PASS',sourceBindings:catalog.files.length,packageBindings:catalog.packages.length,packageMapBindings:mapping.sourceInputs.length,proposed:446,unclassified:0,expectedGateExit:0,ledgerItems:byId.size,acyclic:true,newFindingsReachBaselineReview:true,activeItem:'B04',nextItemStatus:'B05 pending',limits:'Data/source consistency only; no independent tier approval or runtime acceptance.'};
writeFileSync(root+'evidence/B04-batch-8-validation.json',JSON.stringify(record,null,2)+'\n');
console.log(JSON.stringify(record));
